    const haze = 0.2 * (v / 0.35);
    const green = [
      mix(0.42 * t, sky[0], haze),
      mix(0.52 * t, sky[1], haze),
      mix(0.36 * t, sky[2], haze),
    ];
    return [
      [
        mix(sky[0], green[0], foliage),
        mix(sky[1], green[1], foliage),
        mix(sky[2], green[2], foliage),
      ],
    ];
